public static void CreateOrUpdateParameter(ClassName _domain, MethodName _key, Description255 _content, anytype _value)
{
    TFMGenericParms   genericParm;
    ttsbegin;
    select firstonly forupdate genericParm where genericParm.Content == _content &&  genericParm.Domain == _domain && genericParm.Key == _key;

    genericParm.Domain		= _domain;
    genericParm.Value		= [_value];
    genericParm.Key			= _key;
    genericParm.Content		= _content;
    genericParm.ValueString	= strFmt('%1', _value);
    genericParm.write();
    ttscommit;
}

public static anytype getValue(ClassName _domain, MethodName _key, Description255 _content, anytype _defaultValue = null)
{
    TFMGenericParms			genericParm;
    anytype                 retVal = _defaultValue;
    if (!_domain && !_key && !_content)
    {
        return _defaultValue;
    }
    select firstonly forupdate genericParm where genericParm.Content == _content &&  genericParm.Domain == _domain && genericParm.Key == _key;

    if (genericParm.RecId)
    {
        return conPeek(genericParm.Value,1);
    }
    return _defaultValue;
}

public static boolean Exists(ClassName _domain, MethodName _key, Description255 _content)
{
    TFMGenericParms   genericParm;

    select firstonly RecId from genericParm where genericParm.Content == _content &&  genericParm.Domain == _domain && genericParm.Key == _key;
    return genericParm.RecId != 0;
}

public static void Delete(ClassName _domain)
{
    TFMGenericParms   genericParm;
    ttsbegin;
    delete_from genericParm where genericParm.Domain == _domain;
    ttscommit;
}

public static void updateParmsFromOverride(ClassName _domain, Description255 _content, object _instance)
{
    ClassId instanceClassId = classIdGet(_instance);
    Set					methodsOnClass  = TFMFormLookupHelper::parmMethodsOnClass(instanceClassId,false,Types::Class);
    SetEnumerator		sEnum = methodsOnClass.getEnumerator();
    SysDictMethod		dm;
    SysDictClass instanceDC = new SysDictClass(instanceClassId);

    while (sEnum.moveNext())
    {
        //step Through all Parm methods, turn to attributes
        dm = sEnum.current();
        if (TFMGenericParms::Exists(_domain,dm.name(),_content))
        {
            //Update Parameter from Override
            instanceDC.callObject(dm.name(),_instance, TFMGenericParms::getValue(_domain,dm.name(),_content));
        }
    }
}

public static Map makeParmsMapFromOverride(ClassName _domain, Description255 _content, object _instance)
{
    Set					methodsOnClass  = TFMFormLookupHelper::parmMethodsOnClass(classIdGet(_instance),false,Types::Class);
    SetEnumerator		sEnum = methodsOnClass.getEnumerator();
    SysDictMethod		dm;
    SysDictType			sdt;
    SysDictEnum			sde;
    str					systemType;
    Types				thetype;
    str					valueText;
    Map                 retMap = new Map(Types::String, Types::String);

    while (sEnum.moveNext())
    {
        //step Through all Parm methods, turn to Map entry
        dm = sEnum.current();
        if (TFMGenericParms::Exists(_domain,dm.name(),_content))
        {
            retMap.insert(TFMRegistrationCollector::smallBeginnings(subStr(dm.name(),5,100)),strFmt('%1',TFMGenericParms::getValue(_domain,dm.name(),_content)));
        }
    }
    return retMap;
}
